      "evidence_refs": [
        "https://dictionary.cambridge.org/us/dictionary/english/aisle"
      ]
    },
    {
      "subject": "Indonesian answer: lorong toko",
      "conclusion": "Accepted and natural for the stated sense, but not uniquely Indonesian; the phrase is documented in Indonesian retail vocabulary and toko means store/shop.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.sederet.com/tutorial/vocabulary-shopping-belanja/",
        "https://rri.co.id/cirebon/hiburan/2769152/tak-harus-belanja-mengapa-jalan-jalan-ke-toko-bisa-menyenangkan"
      ]
