    {
      "subject": "Malaysian answer: lorong kedai",
      "conclusion": "Accepted and natural for the stated sense. Malaysian dictionary evidence defines kedai as a shop/store and documents lorong kedai usage.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=107200&keyword=kedai",
        "https://www.parlimen.gov.my/files/hindex/pdf/DR-17081995.pdf"
      ]
